// TestCall_AllocBudget asserts that the dispatch pool eliminates steady-state
// allocation after warmup.
// It runs at full arity rather than with two arguments, because the arguments past
// the register lanes are the ones that spill into the argument block; a two-argument
// call can stay allocation-free while a spilling one does not.
func TestCall_AllocBudget(t *testing.T) {
	fn := buildSym(t, srcSum15, "sum15")
	var args [ffi.MaxArgs]uintptr
	for i := range 15 {
		args[i] = uintptr(i + 1)
	}
	if allocs := testing.AllocsPerRun(1000, func() { ffi.Call(fn, 15, &args, 0) }); allocs != 0 {
		t.Fatalf("ffi.Call = %v allocs/op at 15 args, want 0", allocs)
	}
}

